<template>
  <div>
    <div v-show="!isFullscreen" class="fBox" @click="click">
      <div
        class="fullscreenBox"
        style="width: 20px; height: 20px; text-indent: -20px; overflow: hidden"
      >
        <img
          :style="{ filter: `drop-shadow(20px 0px ${topNavFontColor})` }"
          width="20px"
          height="20px"
          src="/img/exit-fullscreen.png"
        />
      </div>
    </div>

    <div v-show="isFullscreen" class="fBox" @click="click">
      <div
        style="width: 20px; height: 20px; text-indent: -20px; overflow: hidden"
        class="fullscreenBox"
      >
        <img
          :style="{ filter: `drop-shadow(20px 0px ${topNavFontColor})` }"
          width="20px"
          height="20px"
          src="/img/fullscreen.png"
        />
      </div>
    </div>
  </div>
</template>

<script>
import screenfull from "screenfull";

export default {
  name: "Screenfull",
  data() {
    return {
      isFullscreen: false,
    };
  },
  computed: {
    topNavFontColor() {
      // return this.$store.state.settings.topNavFontColor;
      return "#fff";
    },
  },
  mounted() {
    this.init();
  },
  beforeDestroy() {
    this.destroy();
  },
  methods: {
    click() {
      if (!screenfull.isEnabled) {
        this.$message({ message: "你的浏览器不支持全屏", type: "warning" });
        return false;
      }
      screenfull.toggle();
    },
    change() {
      this.isFullscreen = screenfull.isFullscreen;
    },
    init() {
      if (screenfull.isEnabled) {
        screenfull.on("change", this.change);
      }
    },
    destroy() {
      if (screenfull.isEnabled) {
        screenfull.off("change", this.change);
      }
    },
  },
};
</script>

