<template>
  <div class="cockpit">
    <img src="/img/cockpit/bg.png" class="cockpit-bg-img" />
    <img
      @click="routerPush('/')"
      src="/img/cockpit/home.png"
      class="cockpit-left-icon cockpit-left-icon-back"
      alt=""
    />
    <div class="cockpit-right-icon cockpit-right-icon-time">{{ nowTime }}</div>
    <screenfull class="cockpit-right-icon cockpit-right-icon-screen" />
    <img
      src="/img/cockpit/leftT.png"
      class="cockpit-border-bg cockpit-border-bg-lt"
    />
    <img
      src="/img/cockpit/rightT.png"
      class="cockpit-border-bg cockpit-border-bg-rt"
    />
    <img
      src="/img/cockpit/leftB.png"
      class="cockpit-border-bg cockpit-border-bg-lb"
    />
    <img
      src="/img/cockpit/rightB.png"
      class="cockpit-border-bg cockpit-border-bg-rb"
    />
    <div class="cockpit-main">
      <mainComp ref="mainComp" />
    </div>
    <leafletMapComp
      class="map"
      ref="leafletMapComp"
      :showToolBox="false"
      :showControl="false"
      :tileLayerConfig="{ layer: 'img8' }"
      @getMapInstance="getMapInstance"
    ></leafletMapComp>
  </div>
</template>

<script>
import mainComp from "@/views/cockpitTemplate/mainComp.vue";
import screenfull from "@/views/cockpitTemplate/screenfull.vue";
import leafletMapComp from "@/components/leafletMapComp/leafletMapComp.vue";

export default {
  name: "parkingCockpit",
  components: {
    mainComp,
    leafletMapComp,
    screenfull,
  },
  data() {
    return {
      nowTimer: null,
      nowTime: "",
      isFullscreen: false,
      mapInstance: undefined,
    };
  },
  watch: {},
  methods: {
    getNowTime() {
      let str = "星期" + "日一二三四五六".charAt(new Date().getDay());
      this.nowTime =
        new Date().toLocaleString().split("/").join("-").split(" ")[0] +
        " " +
        str;
    },

    routerPush(route) {
      this.$router.push(route);
    },

    getMapInstance(instance) {
      this.mapInstance = instance;
    },
  },
  created() {},
  mounted() {
    this.getNowTime();
    this.nowTimer = setInterval(() => {
      this.getNowTime();
    }, 1000 * 60);
  },
  beforeDestroy() {
    if (this.nowTimer) {
      clearInterval(this.nowTimer);
    }
  },
};
</script>
